// In SequentialConcurrentExperiments.cs:
//
// Declare a public sealed class named
// SequentialConcurrentExperiments.
//
// public allows Program.cs to create it.
// sealed prevents inheritance.

// Inside SequentialConcurrentExperiments:
//
// Add a public method named RunAsync.
// It has no parameters and returns Task.
//
// For now, return Task.CompletedTask.
// Do not add async yet.
//
// Task represents eventual completion
// without a returned value.

// Inside SequentialConcurrentExperiments,
// but outside RunAsync:
//
// Add a private method named
// LoadEmployeeNameAsync.
//
// Accept int employeeId and
// int delayMilliseconds.
// Return Task<string>.
//
// For now, return an already-completed
// Task containing string.Empty.
//
// Remember: Task.FromResult is a static
// method call. Do not use new.

// Inside LoadEmployeeNameAsync:
//
// Convert the method to async Task<string>.
// Print a starting message using employeeId.
// Await Task.Delay using delayMilliseconds.
// Print a finished message using employeeId.
// Return text containing Employee and employeeId.
//
// After adding async and await, return the string.
// Do not wrap it in Task.FromResult.
//
// Task.Delay simulates waiting.
// It is not repository I/O and does not
// create a dedicated background thread.

// From the csharp-practice-working solution folder:
//
// Build only the ScratchPad project.

// Run this command in the terminal:
//
// dotnet build src/PinkMachine19.TimeClock.ScratchPad/PinkMachine19.TimeClock.ScratchPad.csproj --configuration Release

// Inside SequentialConcurrentExperiments,
// outside the existing methods:
//
// Add a private method named RunSequentialAsync.
// It has no parameters and returns Task.
//
// For now, return Task.CompletedTask.
// Do not add async yet.

// Inside RunSequentialAsync:
//
// Convert the method to async Task.
// Call LoadEmployeeNameAsync for employee 1
// with a 300 millisecond delay.
// Immediately await it.
// Store the returned string in firstName.
//
// Then call the helper for employee 2
// with a 100 millisecond delay.
// Immediately await it.
// Store the returned string in secondName.
//
// Display both names.
//
// Employee 2 has not started during the first
// await because execution has not reached
// the second method call.

// Inside SequentialConcurrentExperiments,
// outside all existing methods:
//
// Add a private method named RunConcurrentAsync.
// It has no parameters and returns Task.
//
// For now, return Task.CompletedTask.
// Do not add async yet.

// Inside RunConcurrentAsync:
//
// Convert the method to async Task.
// Call LoadEmployeeNameAsync for employee 1
// with a 300 millisecond delay.
// Do not await it yet.
// Store the returned Task<string>
// in a variable named firstTask.
//
// Call the helper for employee 2
// with a 100 millisecond delay.
// Do not await it yet.
// Store the returned Task<string>
// in a variable named secondTask.
//
// Calling both methods before awaiting permits
// their waiting periods to overlap.

// Still inside RunConcurrentAsync:
//
// Pass firstTask and secondTask as arguments
// to Task.WhenAll.
// Await the combined Task.
// Store the returned string array in names.
// Display the returned names.
//
// Do not write Task.WhenAll<string>() with no
// arguments. WhenAll needs the Tasks to combine.
// Both arguments are Task<string>, so the compiler
// infers TResult as string. Await then produces
// string[]. No explicit <string> is needed.
//
// Type inference hides repeated type spelling;
// it does not remove type safety.
// The array follows supplied-Task order,
// not completion order.

// Inside RunAsync:
//
// Remove the temporary implementation.
// Convert RunAsync to async Task.
// Display a Sequential heading.
// Await RunSequentialAsync.
// Display a Concurrent heading.
// Await RunConcurrentAsync.
//
// The demonstrations run one after another
// so their output remains easy to compare.

